    def _remote_ocr(self, img_bytes):
        if not img_bytes:
            return []

        elapsed = time.time() - self._ocr_last_ts
        target_wait = random.uniform(*self._ocr_wait_range)
        if elapsed < target_wait:
            time.sleep(target_wait - elapsed)

        for host in self.OCR_HOSTS:
            try:
                r = requests.post(
                    host + '/fyocr',
                    data=img_bytes,
                    timeout=15,
                    verify=False,
                    headers={
                        "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) "
                                      "AppleWebKit/537.36 (KHTML, like Gecko) "
                                      "Chrome/120.0.0.0 Safari/537.36",
                        "Content-Type": "application/octet-stream",
                        "Referer": host + "/",
                        "Origin": host,
                    },
                )
                self._ocr_last_ts = time.time()

                if r.status_code != 200:
                    continue

                text = (r.text or "").strip()
                if not text.startswith("{"):
                    continue

                try:
                    j = r.json()
                except Exception:
                    continue

                codes = j.get("codes") or []
                codes = [c for c in codes if isinstance(c, str) and 3 <= len(c) <= 8]

                if j.get("code") == 1 and codes:
                    return codes

            except Exception:
                continue

        return []

    def _local_ocr(self, img_bytes, attempt=0):
        codes = []
        try:
            from PIL import Image
            img = Image.open(io.BytesIO(img_bytes)).convert('L')
            w, h = img.size
            img = img.resize((w * 10, h * 10), Image.LANCZOS)
            img = img.point(lambda x: 0 if x < 150 else 255)
            buf = '/tmp/_fy_cap_%d.png' % attempt
            img.save(buf)
            for psm in ('7', '8', '13'):
                res = subprocess.run(['tesseract', buf, 'stdout', '--psm', psm],
                                     capture_output=True, text=True, timeout=20)
                c = (res.stdout or '').strip()
                if c and c not in codes:
                    codes.append(c)
        except Exception:
            pass
        return codes

    def _handle_captcha(self, referer_url, max_attempts=None):
        max_attempts = max_attempts or self._captcha_inner
        mapping = {'0': 'oO', '1': 'lLiI', '2': 'zZ', '5': 'sS',
                   '8': 'bB', '6': 'gG', '3': 'eE', '9': 'gGqQ',
                   '4': 'aA', '7': 'tT'}
        for attempt in range(max_attempts):
            try:
                captcha_url = f"{self.host}/captcha.php?type=code&r={int(time.time()*1000)}"
                img_resp = self._session.get(captcha_url, timeout=15,
                                             headers={'Referer': referer_url})
                if img_resp.status_code != 200:
                    continue

                codes = self._remote_ocr(img_resp.content)
                if not codes:
                    codes = self._local_ocr(img_resp.content, attempt)
                if not codes:
                    time.sleep(1)
                    continue

                ref = referer_url
                try:
                    vb = dict(self._session.cookies).get('verify_back_url', '')
                    if vb:
                        ref = self.host + vb
                except Exception:
                    pass

                ok = False
                for code in codes:
                    if len(code) < 4 or len(code) > 6:
                        continue
                    variants = {code, code.lower(), code.upper()}
                    for ch, reps in mapping.items():
                        if ch in code:
                            for rp in reps:
                                variants.add(code.replace(ch, rp))
                    for variant in variants:
                        if len(variant) != len(code):
                            continue
                        try:
                            submit_resp = self._session.post(
                                f"{self.host}/captcha.php?type=verify",
                                data={'check': variant},
                                headers={
                                    'Content-Type': 'application/x-www-form-urlencoded; charset=utf-8',
                                    'Referer': ref,
                                    'Origin': self.host,
                                    'x-requested-with': 'com.hiker.youtoo'
                                },
                                timeout=15)
                        except Exception:
                            continue
                        if submit_resp.status_code != 200:
                            continue
                        text = submit_resp.text
                        if '"code":1' in text or '验证成功' in text:
                            ok = True
                            break
                        try:
                            if submit_resp.json().get('code') == 1:
                                ok = True
                                break
                        except Exception:
                            pass
                    if ok:
                        break
                if ok:
                    self._save_cookies()
                    return True

                time.sleep(1)
            except Exception:
                continue

        return False

    def _is_captcha_page(self, html):
        return bool(html) and ('验证码' in html or 'verify' in html)

    def _fetch_with_captcha(self, url, max_attempts=None, **kwargs):
        max_attempts = max_attempts or self._captcha_outer
        html = ''
        fail_streak = 0
        for attempt in range(max_attempts):
            try:
                html = self._fetch(url, **kwargs)
                if not html:
                    fail_streak += 1
                    if fail_streak >= self._captcha_fail_streak:
                        return html
                    time.sleep(1)
                    continue

                if not self._is_captcha_page(html):
                    return html

                if self._handle_captcha(url):
                    time.sleep(0.3)
                    html = self._fetch(url, **kwargs)
                    if html and not self._is_captcha_page(html):
                        return html

                fail_streak += 1
                if fail_streak >= self._captcha_fail_streak:
                    return html

                time.sleep(1)
            except Exception:
                fail_streak += 1
                if fail_streak >= self._captcha_fail_streak:
                    return html
                time.sleep(1)
                continue

        return html

