                'qiyi':     ('1', 'https://zzrs.mfdyvip.com/player/?url='),
                'bilibili': ('1', 'https://zzrs.mfdyvip.com/player/?url='),
                'qq':       ('1', 'https://zzrs.mfdyvip.com/player/?url='),
                'youku':    ('1', 'https://zzrs.mfdyvip.com/player/?url='),
            }
            all_apis = [
                'https://zzrs.mfdyvip.com/player/mplayer.php',
                'https://fgsrg.hzqingshan.com/player/mplayer.php',
            ]

            if play_url.startswith('http') and ('.m3u8' in play_url or '.mp4' in play_url):
                result = {"parse": 0, "url": play_url, "header": {'User-Agent': self.headers.get('User-Agent', 'Mozilla/5.0')}}
                self._play_cache[cache_key] = result
                return result

            pconfig = player_config_map.get(play_from)
            if pconfig and pconfig[0] == '1' and pconfig[1]:
                parsed_base = urllib.parse.urlparse(pconfig[1])
                player_domain = f"{parsed_base.scheme}://{parsed_base.netloc}"
                primary_api = f"{player_domain}/player/mplayer.php"
            elif play_from in ('co', 'BBA', 'vwnet', 'YYNB', 'qiyi', 'bilibili', 'qq', 'youku'):
                primary_api = all_apis[0]
            elif play_from in ('JD4K', 'JD2K'):
                primary_api = all_apis[1]
            else:
                flag_lower = flag.lower() if flag else ''
                if '4k' in flag_lower or 'jd' in flag_lower:
                    primary_api = all_apis[1]
                else:
                    primary_api = all_apis[0]

            parsed = self._parse_play_url(play_url, primary_api)
            if parsed:
                result = parsed
                self._play_cache[cache_key] = result
                return result

            for fallback_api in all_apis:
                if fallback_api != primary_api:
                    parsed = self._parse_play_url(play_url, fallback_api)
                    if parsed:
                        result = parsed
                        self._play_cache[cache_key] = result
                        return result

            if play_url.startswith('http'):
                result = {"parse": 0, "url": play_url, "header": {'User-Agent': self.headers.get('User-Agent', 'Mozilla/5.0')}}
            else:
                result = {"parse": 1, "url": play_url_full}
            self._play_cache[cache_key] = result
            return result

        except Exception:
            result = {"parse": 1, "url": ""}
            self._play_cache[cache_key] = result
            return result

    def _parse_play_url(self, play_url, api_url):
        try:
            parsed = urllib.parse.urlparse(api_url)
            player_domain = f"{parsed.scheme}://{parsed.netloc}"

            token_url = f"{player_domain}/player/?url={urllib.parse.quote(play_url, safe='')}"
            headers = {
                'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
                'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8',
                'Accept-Language': 'zh-CN,zh;q=0.9',
                'Referer': 'https://www.ht10010.com/',
            }

            token_resp = self._session.get(token_url, headers=headers, timeout=10)
            if token_resp.status_code != 200:
                return None

            token_match = re.search(r'data-te="([^"]+)"', token_resp.text)
            if not token_match:
                token_match = re.search(r'data-token="([^"]+)"', token_resp.text)
            if not token_match:
                token_match = re.search(r'\btoken["\']?\s*[:=]\s*["\']([^"\']+)', token_resp.text)
            if not token_match:
                return None

            token = token_match.group(1)

            post_headers = {
                'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
                'Content-Type': 'application/x-www-form-urlencoded; charset=UTF-8',
                'Accept': 'application/json, text/javascript, */*; q=0.01',
                'Accept-Language': 'zh-CN,zh;q=0.9',
                'Referer': f'{player_domain}/player/',
                'X-Requested-With': 'XMLHttpRequest',
            }

            payload = {
                'url': play_url,
                'token': token
            }

            resp = self._session.post(api_url, data=payload, headers=post_headers, timeout=15)
            if resp.status_code != 200:
                return None

            final_url = None
            try:
                data = resp.json()
                if data.get('code') in (200, 1, 0) and data.get('url'):
                    final_url = data['url']
                elif data.get('url'):
                    final_url = data['url']
                elif data.get('data') and isinstance(data['data'], dict) and data['data'].get('url'):
                    final_url = data['data']['url']
                elif data.get('data') and isinstance(data['data'], str):
                    final_url = data['data']
            except Exception:
                text = resp.text.strip()
                if text.startswith('http'):
                    final_url = text
                else:
                    url_match = re.search(r'(https?://[^\s"\'<>]+\.m3u8[^\s"\'<>]*|https?://[^\s"\'<>]+\.mp4[^\s"\'<>]*)', text)
                    if url_match:
                        final_url = url_match.group(1)

            if final_url:
                return {
                    "parse": 0,
                    "url": final_url,
                    "header": {'User-Agent': 'Mozilla/5.0 (iPhone; CPU iPhone OS 16_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/16.0 Mobile/15E148 Safari/604.1'}
                }

            return None
        except Exception:
            return None

