    def _load_cookies(self):
        try:
            if os.path.exists(self._ck_file):
                with open(self._ck_file, 'r', encoding='utf-8') as f:
                    data = json.load(f)
                ck = {}
                if isinstance(data, dict):
                    ck = data.get('cookies') or {}
                    if not ck and 'session' in data:
                        ck = data['session'] or {}
                if ck:
                    for k, v in ck.items():
                        try:
                            self._session.cookies.set(k, v)
                        except Exception:
                            pass
        except Exception:
            pass

    def _save_cookies(self):
        try:
            ck = {c.name: c.value for c in self._session.cookies}
            if ck:
                with open(self._ck_file, 'w', encoding='utf-8') as f:
                    json.dump({
                        'cookies': ck,
                        'ts': int(time.time()),
                    }, f, ensure_ascii=False)
        except Exception:
            pass

    def _fetch(self, url, timeout=15):
        try:
            if not url.startswith('http'):
                url = self.host + url
            rsp = self._session.get(url, timeout=timeout)
            return rsp.text if rsp.status_code == 200 else ''
        except Exception:
            return ''

    def _fix_pic(self, u):
        if not u:
            return ''
        if u.startswith('//'):
            return 'https:' + u
        return u.replace('&amp;', '&')

    def _parse_video_list(self, html):
        if not html:
            return []

        videos, seen = [], set()
        soup = BeautifulSoup(html, 'html.parser')

        for a in soup.select('a.public-list-exp'):
            href = a.get('href', '')
            m = re.search(r'/detail/(\d+)\.html', href)
            if not m:
                continue

            vod_id = m.group(1)
            if vod_id in seen:
                continue
            seen.add(vod_id)

            vod_name = a.get('title', '') or ''
            if not vod_name:
                img = a.select_one('img')
                if img:
                    vod_name = img.get('alt', '') or ''

            pic_el = a.select_one('img')
            vod_pic = self._fix_pic(pic_el.get('data-src', '')) if pic_el else ''

            remark_el = a.select_one('.ft2') or a.select_one('.public-list-prb')
            vod_remarks = remark_el.text.strip() if remark_el else ''

            prt_tags = a.select('.public-prt')
            vod_year = prt_tags[1].text.strip() if len(prt_tags) > 1 else ''

            videos.append({
                "vod_id": vod_id,
                "vod_name": vod_name.strip() or "未知影片",
                "vod_pic": vod_pic,
                "vod_remarks": vod_remarks,
                "vod_year": vod_year
            })

        return videos

    def _parse_search_list(self, html):
        if not html:
